-- abt-u3-itsbat-aua: harus menjawab 0|105|5 (nomor 4300-4399 kosong | variabel lama yang dipakai blangko/kueri ada | variabel isian sumber berjenis data_teks). Hanya SELECT.
SELECT CONCAT((SELECT COUNT(*) FROM abt_variabel WHERE no_var BETWEEN 4300 AND 4399),'|',
  (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN ('0001','0007','0012','0015','0017','0032','0033','0046','0048','0053','0068','0098','0141','0143','0155','0194','0279','0281','0306','0312','0364','0366','0378','0650','0651','0690','1001','1002','1003','1025','1033','1046','1061','1197','1198','1199','1200','1201','1202','1203','1204','1205','1206','1207','1208','1217','1241','1242','1246','1247','1358','1359','1509','2026','2224','4004','5058','5059','5105','5125','5174','5178','5197','5223','5368','6032','6033','6034','6060','6063','7029','7030','7036','7046','7047','7082','7095','7211','7212','8004','8008','8010','8087','8184','8185','8500','8501','8502','8505','8554','8555','8560','8601','8602','8605','8606','8607','9003','9250','9251','9277','9278','9709','9710','9958')),'|',
  (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=1046 AND data_type='data_teks') OR (no_var=1357 AND data_type='data_teks') OR (no_var=5197 AND data_type='data_teks') OR (no_var=7211 AND data_type='data_teks') OR (no_var=7212 AND data_type='data_teks'))) AS prasyarat;
